// The build's real identity, generated by scripts/generate-release-info.js.
// Use this — not package.json or hand-written literals — wherever a version is
// shown or sent to the backend.
import generated from '../generated/releaseInfo.json';

// Per-form payload schema versions. Bump one when that form's request shape
// changes incompatibly; stored with drafts/queued records and sent on submit.
export const FORM_SCHEMA_VERSIONS = Object.freeze({
  routine: 1,
  household: 1,
  biannual: 1,
  followup: 1,
});

// Records saved before schema versions existed were built with version 1.
export const LEGACY_FORM_SCHEMA_VERSION = 1;

const FORM_ALIASES = Object.freeze({
  '/form/routine': 'routine', routine: 'routine', routinemonitoring: 'routine',
  '/form/household': 'household', household: 'household',
  '/form/biannual': 'biannual', biannual: 'biannual', concurrent: 'biannual',
  '/form/followup': 'followup', followup: 'followup',
});

/** Canonical form key ('routine' | 'household' | 'biannual' | 'followup') for a submit url or draft type. */
export function formKeyFor(urlOrType) {
  if (!urlOrType) return null;
  const k = String(urlOrType).split('?')[0].toLowerCase();
  return FORM_ALIASES[k] || null;
}

/** Schema version THIS build uses for a form (null for urls that are not survey submissions). */
export function formSchemaVersionFor(urlOrType) {
  const key = formKeyFor(urlOrType);
  return key ? FORM_SCHEMA_VERSIONS[key] : null;
}

export const RELEASE_INFO = Object.freeze({
  ...generated,
  formSchemaVersions: FORM_SCHEMA_VERSIONS,
  // e.g. "sam-1.0.11 (#14) · 7d1498f" — the commit tells support exactly which build this is.
  displayVersion: [
    generated.releaseSequence ? `${generated.releaseId} (#${generated.releaseSequence})` : generated.releaseId,
    `${String(generated.frontendCommit).slice(0, 7)}${generated.dirty ? '-dirty' : ''}`,
  ].join(' · '),
});
